```sql
/* Список описаний блюд на вынос (takeaway) с любой датой "best before" */
/* и описаний готовых блюд (prepared) с датой "best before" = 10.11.2018 */
SELECT
    m."description",
    m."bestbefore"
FROM "meals" AS m
WHERE
    /* takeaway: любая дата bestbefore */
    LOWER(m."mealtype") = 'takeaway'
    /* prepared: дата bestbefore = 10.11.2018 (преобразуем TEXT в DATE) */
    OR (
        LOWER(m."mealtype") = 'prepared'
        AND TO_DATE(m."bestbefore", 'DD.MM.YYYY') = TO_DATE('10.11.2018', 'DD.MM.YYYY')
    );
```

```sql
/* Выбираем типы и описания образцов, которые встречаются у всех геологов */
SELECT s."type", s."description"
FROM "specimens" s
WHERE s."type" IN (
    /* Типы образцов, которые есть у каждого геолога */
    SELECT gs."specimentype"
    FROM "geologists_specimens" gs
    GROUP BY gs."specimentype"
    HAVING COUNT(DISTINCT gs."geologistid") = (SELECT COUNT(*) FROM "geologists")
)
ORDER BY s."type" ASC NULLS FIRST, s."description" ASC NULLS FIRST;
```

